function [pulse_train, outs]=decheveigne2023(insig_drive,fs,varargin)%DECHEVEIGNE2023%%   Usage:%     [pulse_train, outs] = decheveigne2023(insig_drive,fs,varargin) - %       generates a pulse train given a specific input drive function. The%       simplest driving function is a constant value , indicating a rate%       expressed in spikes/s. This model can be used to convert ideal driving%       functions as, e.g., given by auditory-nerve (AN) models mimicking %       average firing rates into AN train pulses.%           This model is based on thinning (performed in %       decheveigne2023_spiketrain.m) that can optionally account for %       (further thinning) refractoriness (decheveigne2023_spikerefractory.m) %       and jitter (decheveigne2023_spikejitter.m).%           Every stage gives as output the spike probabilities (variable %       output_spikes) and after the last thinning process, these spikes are%       converted into a pulse train (decheveigne2023_spiketopulse.m).%%   Input parameters:%     insig_drive: Drive function with amplitudes indicating average firing%         rates expressed in spikes/s.%     fs: sampling rate (Hz)%%   Output parameters:%     pulse_train: time series of pulses%     outs: struct containing %%   References: decheveigne2023%   #StatusDoc: Unknown%   #StatusCode: Unknown%   #Verification: Unknown%   #Requirements: Unknown%   #Author: Alain de Cheveigne (2023)%   #Authors: Alejandro Osses (2023): integration in AMT 1.5% This file is licensed unter the GNU General Public License (GPL) either % version 3 of the license, or any later version as published by the Free Software % Foundation. Details of the GPLv3 can be found in the AMT directory "licences" and % at <https://www.gnu.org/licenses/gpl-3.0.html>. % You can redistribute this file and/or modify it under the terms of the GPLv3. % This file is distributed without any warranty; without even the implied warranty % of merchantability or fitness for a particular purpose. definput.import={'decheveigne2023'}; [flags,keyvals]  = ltfatarghelper({},definput,varargin);output_spikes = decheveigne2023_spiketrain(insig_drive,fs,keyvals.recfun,keyvals.nfibers);output_spikes_description = 'Spikes after decheveigne2023_spiketrain.m';if flags.do_refractoriness    % A new pulse train will be generated from 'output spikes', after adding     %   the refractory effects, so, we stored the pulse train and spikes before    %   this process:    output_spikes_before_refractoriness = output_spikes;        output_spikes = decheveigne2023_spikerefractory(output_spikes,keyvals.dead_time);    output_spikes_description = 'Spikes after decheveigne2023_spikerefractory.m';endif flags.do_jitter    output_spikes = decheveigne2023_spikejitter(output_spikes,keyvals.sigma);    output_spikes_description = 'Spikes after decheveigne2023_spikejitter.m';endpulse_train = decheveigne2023_spiketopulse(output_spikes,fs);outs = [];outs.output_spikes             = output_spikes;outs.output_spikes_description = output_spikes_description;if flags.do_refractoriness    outs.output_spikes_before_refractoriness = output_spikes_before_refractoriness;end
